FUNCTION handleDeleteShift(request, shift_id):
    // REQ-4-021; preconditions: existing shift and persistence available.
    REQUIRE admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF any seating references shift THEN ROLLBACK; RETURN 409. END IF MARK deleted; COMMIT; RETURN 204.
    // REQ-4-007; repeat is 404; rollback leaves every relation unchanged.

FUNCTION handleDeleteTable(request, table_id):
    // REQ-4-016; preconditions: existing table and persistence available.
    REQUIRE admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF any seating references table THEN ROLLBACK; RETURN 409. END IF MARK deleted; COMMIT; RETURN 204.
    // REQ-4-007; repeat is 404; rollback postcondition preserves all relationships.

FUNCTION handlePatchSeating(request, seating_id):
    // REQ-4-025; preconditions: JSON, existing seating, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415. BEGIN TRANSACTION; IF status is not BOOKED THEN ROLLBACK; RETURN 409. END IF
    VALIDATE result OR ROLLBACK; RETURN 400 or 422; lock target turn; IF capacity or uniqueness fails THEN ROLLBACK; RETURN 409. END IF UPDATE; COMMIT; RETURN 200.
    // Idempotent identical payload; rollback leaves all relations unchanged.

FUNCTION handlePatchShift(request, shift_id):
    // REQ-4-020; preconditions: existing shift, JSON, persistence available.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE resulting REQ-4-003 values OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF any seating references shift THEN ROLLBACK; RETURN 409. END IF UPDATE supplied fields; COMMIT; RETURN 200.
    // Identical payload is idempotent; rollback preserves shift-table-seating relations.

FUNCTION handlePatchTable(request, table_id):
    // REQ-4-015; preconditions: existing table, JSON, persistence available.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE partial result OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF duplicate code, active seating exceeds new seats, or deactivation has BOOKED or SEATED rows THEN ROLLBACK; RETURN 409. END IF UPDATE; COMMIT; RETURN 200.
    // Idempotent identical payload; rollback leaves table-shift-seating relations unchanged.

FUNCTION handleCreateSeating(request):
    // REQ-4-023; preconditions: JSON, active table and shift, persistence available.
    REQUIRE authenticated user or admin OR RETURN 401; REQUIRE JSON OR RETURN 415; VALIDATE body OR RETURN 400 or 422; missing table or shift is 404.
    BEGIN TRANSACTION; lock table, shift, and turn. IF capacity, turn, or uniqueness rule fails THEN ROLLBACK; RETURN 409. END IF CREATE BOOKED seating with caller; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves all relations under REQ-4-010.

FUNCTION handleCancelSeating(request, seating_id):
    // REQ-4-026; preconditions: JSON, existing seating, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE timestamp OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF terminal status THEN ROLLBACK; RETURN 409. END IF SET CANCELLED and retain relations; COMMIT; RETURN 200.
    // REQ-4-006 and REQ-4-010; non-idempotent, and rollback preserves all state.

FUNCTION handleCreateShift(request):
    // REQ-4-018; preconditions: JSON and persistence available.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE REQ-4-001 and REQ-4-003 OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF date and kind exists THEN ROLLBACK; RETURN 409. END IF CREATE shift; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves tables and all seating relations.

FUNCTION handleCreateTable(request):
    // REQ-4-013; preconditions: JSON and persistence available.
    REQUIRE authenticated admin OR RETURN 401 or 403; REQUIRE application/json OR RETURN 415; VALIDATE REQ-4-002 OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF code exists THEN ROLLBACK; RETURN 409. END IF CREATE table; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback postcondition preserves tables, shifts, and relations.
